from datetime import timedelta
import random

import config
import database
import friends
import gaps
import models
import recommender
import support
import synthetic_data


class SyntheticDataTests(support.DatabaseCase):
    """Exercise complete generation against isolated files and a fixed local clock."""

    def setUp(self):
        """Import all demo sources and generate sixty users before each independent check."""
        super().setUp()
        synthetic_data.generate_all(self.connection, support.NOW.date(), now=support.NOW,
                                     **self.paths)
        self.demo_path = self.directory / 'demo' / config.DEMO_CALENDAR_FILE.name

    def test_sanity_preferences_and_symmetric_friendships(self):
        """Require balanced labels, all directions, valid profiles and three to six friends."""
        summary = synthetic_data.check_synthetic_data(self.connection, support.NOW)
        self.assertGreaterEqual(summary['rated_interactions'], config.SYNTHETIC_MIN_RATINGS)
        self.assertTrue(0.35 <= summary['positive_share'] <= 0.65)
        users = database.get_synthetic_users_df(self.connection)
        self.assertEqual(len(users), config.N_SYNTHETIC_USERS)
        self.assertEqual(list(users['friend_code'].head(6)), list(config.SHOWCASE_CODES))
        self.assertTrue(users['sharing_opt_in'].head(6).all())
        for user_id in users.index:
            user_id = int(user_id)
            profile = database.get_user_profile(self.connection, user_id)
            self.assertTrue(1 <= len(profile.directions) <= 3)
            self.assertTrue(1 <= len(profile.favorite_bundle_keys) <= 3)
            count = self.scalar('SELECT COUNT(*) FROM friendships WHERE user_id=?', (user_id,))
            self.assertTrue(3 <= count <= 6)
        asymmetric = self.scalar('''SELECT COUNT(*) FROM friendships f WHERE NOT EXISTS
            (SELECT 1 FROM friendships r WHERE r.user_id=f.friend_id AND r.friend_id=f.user_id)''')
        self.assertEqual(asymmetric, 0)

    def test_repeatability_and_idempotent_upgrade(self):
        """Reproduce a fresh seed despite unrelated random calls and repeated upgrades."""
        other = database.get_connection(':memory:')
        self.addCleanup(other.close)
        database.init_db(other)
        random.Random(999).random()
        synthetic_data.generate_all(other, support.NOW.date(), now=support.NOW, **self.paths)
        for query in ('SELECT * FROM users', 'SELECT * FROM user_directions',
                      'SELECT * FROM favorites', 'SELECT * FROM friendships',
                      'SELECT * FROM interactions', 'SELECT * FROM events'):
            left = [tuple(row) for row in self.connection.execute(query)]
            right = [tuple(row) for row in other.execute(query)]
            self.assertEqual(left, right)
        before = database.get_rating_cache_key(self.connection)
        synthetic_data.ensure_synthetic_data(self.connection, support.NOW)
        self.assertEqual(database.get_rating_cache_key(self.connection), before)
        self.assertEqual(len(database.get_synthetic_users_df(self.connection)), 60)

    def test_state_timestamps_cleanup_and_training(self):
        """Keep only referenced history and train only on attended, available rated rows."""
        rows = self.connection.execute('''SELECT i.*,e.start_time,e.end_time FROM interactions i
            JOIN events e ON e.id=i.event_id''').fetchall()
        for row in rows:
            self.assertLess(row['confirmed_at'], row['start_time'])
            if row['answered_at'] is not None:
                self.assertGreater(row['answered_at'], row['end_time'])
                self.assertLessEqual(row['answered_at'], database.to_db_text(support.NOW))
            if row['status'] != 'attended':
                self.assertIsNone(row['rating'])
        self.assertEqual(self.scalar('''SELECT COUNT(*) FROM events e WHERE e.end_time<?
            AND NOT EXISTS (SELECT 1 FROM interactions i WHERE i.event_id=e.id)''',
            (database.to_db_text(support.NOW),)), 0)
        X, y, weights = recommender.build_training_data(self.connection, support.NOW)
        self.assertGreaterEqual(len(X), 500)
        self.assertEqual(set(y), {0, 1})
        self.assertEqual(set(weights), {config.SYNTHETIC_SAMPLE_WEIGHT})

    def test_generated_model_changes_same_gap_top_three(self):
        """Use generated ratings to personalize six candidates in the same two-hour gap."""
        X, y, weights = recommender.build_training_data(self.connection, support.NOW)
        scorer = recommender.Recommender(recommender.train_production_model(X, y, weights),
                                         X.columns)
        events = []
        for index in range(6):
            direction = 'sports' if index < 3 else 'career'
            bundle = 'sports_ball' if direction == 'sports' else 'career_tech'
            events.append(support.event(event_id=index + 1, direction_key=direction,
                                         bundle_key=bundle, price='0'))
        gap = models.Gap(support.NOW.date(), support.NOW, support.NOW + timedelta(hours=2))
        self.assertTrue(all(gap.fits(event) for event in events))
        results = []
        for direction in ('sports', 'career'):
            profile = models.UserProfile(1, 'Alex', 'ALEX23', {direction})
            top = scorer.score_events(events, profile)[:3]
            results.append([item.event.event_id for item in top])
            self.assertEqual({item.event.direction_key for item in top}, {direction})
        self.assertNotEqual(results[0], results[1])

    def test_local_history_and_showcase(self):
        """Create six demo rows, two pending answers and three showcase friends."""
        user_id = database.complete_onboarding(self.connection, 'Alex', config.DIRECTION_LABELS,
                                                'demo', support.NOW, load_demo_history=True)
        ids = synthetic_data.create_demo_history(self.connection, user_id, support.NOW,
                                                 self.demo_path)
        self.assertEqual(len(ids), 6)
        rows = database.get_user_interactions_df(self.connection, user_id)
        self.assertEqual(set(rows['is_demo']), {1})
        self.assertEqual(sorted(rows['rating'].dropna()), [2, 4, 5])
        pending = database.get_pending_feedback(self.connection, user_id, support.NOW)
        self.assertEqual(len(pending), 2)
        again = synthetic_data.create_demo_history(self.connection, user_id, support.NOW,
                                                   self.demo_path)
        self.assertEqual(again, ids)
        synthetic_data.create_showcase_friends(self.connection, user_id, support.NOW,
                                                self.demo_path)
        synthetic_data.create_showcase_friends(self.connection, user_id, support.NOW,
                                                self.demo_path)
        count = self.scalar('SELECT COUNT(*) FROM friendships WHERE user_id=?', (user_id,))
        self.assertEqual(count, 3)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM invitations WHERE recipient_id=?',
                                     (user_id,)), 2)
        counts = friends.friends_going_counts(self.connection, user_id,
                                              database.get_known_event_ids(self.connection))
        self.assertTrue(any(count == 3 for count in counts.values()))

    def test_empty_demo_candidates_do_not_fail(self):
        """Return an empty history when there are no eligible events without inventing any."""
        user_id = database.create_user(self.connection, 'Alex', now=support.NOW)
        database.set_user_directions(self.connection, user_id, {'career'})
        future = support.NOW + timedelta(weeks=config.FUTURE_WEEKS + 2)
        self.assertEqual(synthetic_data.create_demo_history(self.connection, user_id, future,
                                                            self.demo_path), [])

    def test_first_week_contains_a_future_trip(self):
        """Keep an open off-site trip in the first demo week for M8's Beyond-your-gaps step."""
        end = support.NOW + timedelta(days=config.DAYS_PER_WEEK)
        frame = database.get_events_df(self.connection, support.NOW, end)
        trips = frame.loc[frame['event_type'] == 'Trip']
        self.assertFalse(trips.empty)
        self.assertTrue((trips['status'] == 'open').all())
        self.assertTrue((trips['location_type'] == 'elsewhere').all())

    def test_showcase_skips_an_event_starting_exactly_now(self):
        """Never confirm an already starting occurrence while preparing showcase plans."""
        start = (support.NOW + timedelta(days=1)).replace(hour=12, minute=15)
        self.save([support.record(external_id='starting-now', start=start,
                                  end=start + timedelta(hours=1))])
        event_id = self.scalar('SELECT MAX(id) FROM events')
        uid = database.create_user(self.connection, 'Alex', now=support.NOW)
        synthetic_data.create_showcase_friends(self.connection, uid, start, self.demo_path)
        showcase = database.get_synthetic_users_df(self.connection).head(3)
        for friend_id in showcase.index:
            self.assertIsNone(database.get_interaction(self.connection, int(friend_id), event_id))

    def test_sanity_rejects_bad_data(self):
        """Reject one-class or missing training data with an actionable failure."""
        with self.connection:
            self.connection.execute('UPDATE interactions SET rating=5 WHERE rating IS NOT NULL')
        with self.assertRaisesRegex(ValueError, 'outside 35–65%'):
            synthetic_data.check_synthetic_data(self.connection, support.NOW)
        with self.connection:
            self.connection.execute('UPDATE interactions SET rating=NULL')
        with self.assertRaisesRegex(ValueError, 'at least 500'):
            synthetic_data.check_synthetic_data(self.connection, support.NOW)

    def test_upgrade_preserves_local_data_and_explicit_reset_clears_it(self):
        """Repair an incomplete synthetic seed while preserving a genuine local rating and files."""
        uid = database.complete_onboarding(self.connection, 'Alex', {'sports'}, 'demo', support.NOW)
        event_id = int(database.get_training_interactions_df(self.connection, support.NOW)
                       ['event_id'].iloc[0])
        event = models.event_from_row(database.get_event_row(self.connection, event_id))
        database.save_interaction(self.connection, uid, event_id, 'confirm',
                                  now=event.start - timedelta(days=1))
        database.save_interaction(self.connection, uid, event_id, 'attended', now=support.NOW)
        database.save_interaction(self.connection, uid, event_id, 'rate', 5, support.NOW)
        before = database.get_interaction(self.connection, uid, event_id)
        database.set_setting(self.connection, 'synthetic_setup_done', '0')
        synthetic_data.ensure_synthetic_data(self.connection, support.NOW)
        self.assertEqual(database.get_current_user_id(self.connection), uid)
        self.assertEqual(database.get_interaction(self.connection, uid, event_id), before)
        self.assertEqual(len(database.get_synthetic_users_df(self.connection)), 60)
        private = self.directory / 'private-calendar.ics'
        private.write_text('private fixture', encoding='utf-8')
        database.reset_database(self.connection)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM users'), 0)
        self.assertIsNone(database.get_setting(self.connection, 'setup_done'))
        self.assertEqual(private.read_text(encoding='utf-8'), 'private fixture')
